class Solution {
public:
    int parent[200005];
    int spf[100005];

    int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    void unite(int x, int y) {
        int px = find(x), py = find(y);
        if (px != py) parent[px] = py;
    }

    bool canTraverseAllPairs(vector<int>& nums) {
        int n = nums.size();
        if (n == 1) return true;

        int M = 100000;
        for (int i = 0; i <= M; i++) spf[i] = i;
        for (int i = 2; i * i <= M; i++) {
            if (spf[i] == i) {
                for (int j = i * i; j <= M; j += i) {
                    if (spf[j] == j) spf[j] = i;
                }
            }
        }

        int total = n + M + 1;
        for (int i = 0; i < total; i++) parent[i] = i;

        for (int i = 0; i < n; i++) {
            int v = nums[i];
            if (v == 1) return false;
            while (v > 1) {
                int p = spf[v];
                unite(i, n + p);
                while (v % p == 0) v /= p;
            }
        }

        int root = find(0);
        for (int i = 1; i < n; i++) {
            if (find(i) != root) return false;
        }
        return true;
    }
};
